    @BeforeEach
    void setup() throws IOException, InterruptedException {
// reset state of the test db
        ProcessBuilder pb = new ProcessBuilder("./db_create_test.sh");
        pb.directory(new File("assets"));

        Process p = pb.start();

        int exitVal = p.waitFor();
        assert exitVal == 0 : new BufferedReader(new InputStreamReader(p.getErrorStream()))
                .lines().collect(Collectors.joining("\n"));

//        connect to db
        c = Database.connectToSqlTest();
        db = new Database(c);

        //     change system.out to this custom printstream we create so that
//       we can test what gets printed out
        baos = new ByteArrayOutputStream();
        ps = new PrintStream(baos);

    }

    @AfterEach
    void cleanup() throws IOException, SQLException {
        baos.close();
        ps.close();

//        close db connection
        c.close();
    }

    private void userUiHelper(String input, String expectedOutput) {
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));
        UserUI u = new UserUI(db, sc, ps);
        u.setDefaultDate();
        u.start();
        assertEquals(expectedOutput, baos.toString());
        sc.close();
    }

    private void StaffUiHelper(String input, String expectedOutput) {
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));
        StaffUI s = new StaffUI(db, sc, ps);
        s.setDefaultDate();
        s.start();
        assertEquals(expectedOutput, baos.toString());
        sc.close();
    }

