    @Test
    void creditCardTest() {
//        assert thsi is a valid credit card
        assertTrue(CreditCard.isValid("40691", "Charles"));
        //        assert thsi is not a valid credit card (invalid number)
        assertFalse(CreditCard.isValid("42688", "Sergio"));
        //        assert thsi is not a valid credit card (correct number but invalid name)
        assertFalse(CreditCard.isValid("42689", "Sergoi"));

    }

    @Test
    void creditCardPayment() {
        String input = "42689\nSergio\nno\n";
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));

        UserUI u = new UserUI(db, sc, ps);
        assertTrue(u.payWithCreditCard());

        String expected = "[] Enter your credit card number: \n" +
                "[] Enter the name associated with the credit card: \n" +
                "[] Would you like to save your card number and details so you don't need to enter them again in future transactions? (yes/no): \n";
        assertEquals(expected, baos.toString());

        sc.close();
    }

    @Test
    void creditCardSaved() {
        String input = "yes\n";
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));

        UserUI u = new UserUI(db, sc, ps);
        u.setUser("adam");
        assertTrue(u.payWithCreditCard());

        String expected = "[] It looks like you have your credit card details saved from a previous transaction. Would you like to auto-fill these details? (yes/no): \n";
        assertEquals(expected, baos.toString());

        sc.close();
    }

    @Test
    void creditCardFailOnce() {
        String input = "42688\nSergio\n42689\nSergio\nno\n";
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));

        UserUI u = new UserUI(db, sc, ps);
        assertTrue(u.payWithCreditCard());

        String expected = "[] Enter your credit card number: \n" +
                "[] Enter the name associated with the credit card: \n" +
                "[] Invalid credit card details! Please try again.\n" +
                "[] Enter your credit card number: \n" +
                "[] Enter the name associated with the credit card: \n" +
                "[] Would you like to save your card number and details so you don't need to enter them again in future transactions? (yes/no): \n";
        assertEquals(expected, baos.toString());

        sc.close();
    }

    @Test void registerAccount() {
        String input = "basem\nabc\n";
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));

        UserUI u = new UserUI(db, sc, ps);
        assertTrue(u.registerAccount());

        String expected = "[] Enter a username: \n" +
                "[] Enter a password: \n" +
                "[] Registration complete!\n";
        assertEquals(expected, baos.toString());

        sc.close();
    }
    @Test void registerAccountFails() {
        String input = "alex\nabc\n";
        Scanner sc = new Scanner(new ByteArrayInputStream(input.getBytes()));

        UserUI u = new UserUI(db, sc, ps);
        assertFalse(u.registerAccount());

        String expected = "[] Enter a username: \n" +
                "[] Enter a password: \n" +
                "[] Failed to register! The username may already be taken.\n";
        assertEquals(expected, baos.toString());

        sc.close();
    }

